// IdentityRecord represents a decentralized identity
// GDPR-compliant: stores only cryptographic commitments, not raw PII
type IdentityRecord struct {
	// Decentralized identifier (DID)
	Did string `protobuf:"bytes,1,opt,name=did,proto3" json:"did,omitempty"`
	// Associated blockchain address
	Address string `protobuf:"bytes,2,opt,name=address,proto3" json:"address,omitempty"`
	// Current status of identity
	Status IdentityStatus `protobuf:"varint,3,opt,name=status,proto3,enum=aura.identity.v1beta1.IdentityStatus" json:"status,omitempty"`
	// Timestamp when identity was created
	CreatedAt time.Time `protobuf:"bytes,4,opt,name=created_at,json=createdAt,proto3,stdtime" json:"created_at"`
	// Timestamp when identity was last updated
	UpdatedAt *time.Time `protobuf:"bytes,5,opt,name=updated_at,json=updatedAt,proto3,stdtime" json:"updated_at,omitempty"`
	// List of verification methods (public keys, not PII)
	VerificationMethods []string `protobuf:"bytes,7,rep,name=verification_methods,json=verificationMethods,proto3" json:"verification_methods,omitempty"`
	// Confidence score (0-100)
	ConfidenceScore int64 `protobuf:"varint,8,opt,name=confidence_score,json=confidenceScore,proto3" json:"confidence_score,omitempty"`
	// Metadata hash (hash of off-chain metadata, not the metadata itself)
	MetadataHash string `protobuf:"bytes,9,opt,name=metadata_hash,json=metadataHash,proto3" json:"metadata_hash,omitempty"`
	// Latest inclusion routine version
	LatestIrVersion string `protobuf:"bytes,10,opt,name=latest_ir_version,json=latestIrVersion,proto3" json:"latest_ir_version,omitempty"`
	// Block height of last change
	LastChangedHeight int64 `protobuf:"varint,11,opt,name=last_changed_height,json=lastChangedHeight,proto3" json:"last_changed_height,omitempty"`
	// Cryptographic commitment to PII data (SHA-256 hash)
	// Commitment = SHA256(sorted_attributes || salt)
	// This allows verification without storing raw PII on-chain
	PiiCommitment []byte `protobuf:"bytes,12,opt,name=pii_commitment,json=piiCommitment,proto3" json:"pii_commitment,omitempty"`
	// Salt used in PII commitment (random 32 bytes)
	// Stored on-chain to allow verification but prevents rainbow table attacks
	CommitmentSalt []byte `protobuf:"bytes,13,opt,name=commitment_salt,json=commitmentSalt,proto3" json:"commitment_salt,omitempty"`
	// GDPR Right to Erasure flag
	// When true, PII has been erased but audit trail (commitment) remains
	Erased bool `protobuf:"varint,14,opt,name=erased,proto3" json:"erased,omitempty"`
	// Timestamp when identity was erased (GDPR compliance)
	ErasedAt *time.Time `protobuf:"bytes,15,opt,name=erased_at,json=erasedAt,proto3,stdtime" json:"erased_at,omitempty"`
	// Off-chain data reference (IPFS CID, secure URL, or data location hint)
	// Actual PII stored here, not on-chain
	OffChainDataRef string `protobuf:"bytes,16,opt,name=off_chain_data_ref,json=offChainDataRef,proto3" json:"off_chain_data_ref,omitempty"`
	// Off-chain data reference type (ipfs, https, did-document, etc.)
	OffChainDataType     string   `protobuf:"bytes,17,opt,name=off_chain_data_type,json=offChainDataType,proto3" json:"off_chain_data_type,omitempty"`
	XXX_NoUnkeyedLiteral struct{} `json:"-"`
	XXX_unrecognized     []byte   `json:"-"`
	XXX_sizecache        int32    `json:"-"`
}

